+export interface SshForwardRuntime { profileId: string; generation: WireCounter; state: "stopped" | "starting" | "running" | "reconnecting" | "stopping" | "failed"; bindHost: "127.0.0.1"; localPort: number; retryAttempt: number; activeChannels: number; autoStartDisposition: "notRequested" | "queued" | "started" | "skippedActiveLimit"; stateChangedAt: UtcTimestamp; startedAt?: UtcTimestamp; errorCode?: SshForwardErrorCode; }
+export interface HostKeyChallenge { challengeId: string; profileId: string; scopeId: string; generation: WireCounter; sshHost: string; sshPort: number; algorithm: string; fingerprint: string; expiresAt: UtcTimestamp; }
+export interface SshForwardSnapshot { context: DesktopClientContext; scopeId: string; activationToken: WireCounter; scopeGeneration: WireCounter; profilesRevision: WireCounter; trustRevision: WireCounter; profiles: SshForwardProfile[]; runtimes: SshForwardRuntime[]; hostKeyChallenges: HostKeyChallenge[]; }
