+export interface SshForwardError { code: SshForwardErrorCode; message: string; retryable: boolean; scopeId?: string; profileId?: string; currentProfilesRevision?: WireCounter; currentTrustRevision?: WireCounter; currentScopeGeneration?: WireCounter; currentGeneration?: WireCounter; }
+const SSH_FORWARD_ERROR_CODES: readonly SshForwardErrorCode[] = ["INVALID_ARGUMENT", "UNSUPPORTED_PLATFORM", "IPC_UNAVAILABLE", "DESKTOP_INSTANCE_MISMATCH", "MANAGER_SESSION_MISMATCH", "CLIENT_EPOCH_STALE", "ACTIVATION_SUPERSEDED", "SCOPE_NOT_ACTIVE", "SCOPE_GENERATION_CONFLICT", "SCOPE_ACTIVE", "SCOPE_PURGE_FAILED", "PROFILES_REVISION_CONFLICT", "TRUST_REVISION_CONFLICT", "GENERATION_CONFLICT", "COUNTER_EXHAUSTED", "PROFILE_NOT_FOUND", "PROFILE_ACTIVE", "PROFILE_LIMIT", "ACTIVE_FORWARD_LIMIT", "AUTO_START_SKIPPED_LIMIT", "KEY_NOT_FOUND", "KEY_UNSAFE", "KEY_ENCRYPTED_USE_AGENT", "AGENT_UNAVAILABLE", "HOST_KEY_APPROVAL_REQUIRED", "HOST_KEY_CHANGED", "HOST_KEY_ALGORITHM_CHANGED", "HOST_KEY_ALGORITHM_UNSUPPORTED", "HOST_KEY_CHALLENGE_NOT_FOUND", "HOST_KEY_CHALLENGE_EXPIRED", "SSH_CONNECT_TIMEOUT", "SSH_CONNECT_FAILED", "AUTH_FAILED", "LOCAL_PORT_IN_USE", "BIND_FAILED", "CHANNEL_OPEN_TIMEOUT", "TARGET_CONNECT_FAILED", "TARGET_NOT_ALLOWED", "SHUTDOWN_TIMEOUT", "SHUTDOWN_IN_PROGRESS", "STORE_CORRUPT", "STORE_IO", "INTERNAL", "INVALID_COUNTER", "INVALID_TIMESTAMP", "INVALID_PROFILE", "IDENTITY_CORRUPT", "STALE_CLIENT", "STORAGE_UNAVAILABLE"];
