+export function parseSshForwardError(value: unknown): SshForwardError | null {
+  if (!value || typeof value !== "object") return null;
+  const raw = value as Record<string, unknown>;
+  if (typeof raw.code !== "string" || !SSH_FORWARD_ERROR_CODES.includes(raw.code as SshForwardErrorCode) || typeof raw.message !== "string" || typeof raw.retryable !== "boolean") return null;
+  const counter = (candidate: unknown) => candidate === undefined || Boolean(parseWireCounter(candidate));
+  if (!counter(raw.currentProfilesRevision) || !counter(raw.currentTrustRevision) || !counter(raw.currentScopeGeneration) || !counter(raw.currentGeneration)) return null;
+  if ((raw.scopeId !== undefined && typeof raw.scopeId !== "string") || (raw.profileId !== undefined && typeof raw.profileId !== "string")) return null;
+  return { code: raw.code as SshForwardErrorCode, message: raw.message, retryable: raw.retryable, ...(typeof raw.scopeId === "string" ? { scopeId: raw.scopeId } : {}), ...(typeof raw.profileId === "string" ? { profileId: raw.profileId } : {}), ...(parseWireCounter(raw.currentProfilesRevision) ? { currentProfilesRevision: parseWireCounter(raw.currentProfilesRevision)! } : {}), ...(parseWireCounter(raw.currentTrustRevision) ? { currentTrustRevision: parseWireCounter(raw.currentTrustRevision)! } : {}), ...(parseWireCounter(raw.currentScopeGeneration) ? { currentScopeGeneration: parseWireCounter(raw.currentScopeGeneration)! } : {}), ...(parseWireCounter(raw.currentGeneration) ? { currentGeneration: parseWireCounter(raw.currentGeneration)! } : {}) };
