+export interface SshForwardEventHint { desktopInstanceId: string; managerSessionId: string; clientEpoch: WireCounter; activationToken: WireCounter; scopeId: string; scopeGeneration: WireCounter; profilesRevision: WireCounter; trustRevision: WireCounter; profileId?: string; generation?: WireCounter; reason: "profilesChanged" | "runtimeChanged" | "trustChanged"; }
