+  restart(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
+  listKeys(): Promise<KeyInventory>;
+  approveHost(profileId: string, expectedGeneration: WireCounter, challengeId: string, algorithm: string, fingerprint: string): Promise<SshForwardSnapshot>;
