   459	  }
   460	  return false;
   461	}
   462	
   463	/** Delete a profile by ID */
   464	export function deleteProfile(id: string): boolean {
   465	  const previousProfiles = getProfiles();
   466	  const profile = previousProfiles.find((candidate) => candidate.id === id);
   467	  if (!profile) return false;
   468	
   469	  const previousActiveId = getActiveProfileId();
   470	  const previousToken = getAuthToken(id);
   471	  const nextProfiles = previousProfiles.filter(
   472	    (candidate) => candidate.id !== id,
   473	  );
   474	  const restoreToken = () => {
   475	    if (!previousToken) return clearAuthToken(id);
   476	    return (
   477	      setAuthToken(previousToken, id) && getAuthToken(id) === previousToken
   478	    );
   479	  };
   480	
   481	  if (!clearAuthToken(id)) {
   482	    restoreToken();
   483	    return false;
   484	  }
   485	
   486	  if (!saveProfiles(nextProfiles)) {
   487	    restoreToken();
   488	    return false;
   489	  }
   490	
   491	  if (previousActiveId === id) {
   492	    const activeUpdated = nextProfiles[0]
   493	      ? setActiveProfile(nextProfiles[0].id)
   494	      : clearActiveProfile();
   495	    if (!activeUpdated) {
   496	      const profilesRestored = saveProfiles(previousProfiles);
   497	      const activeRestored = previousActiveId
   498	        ? setActiveProfile(previousActiveId)
   499	        : clearActiveProfile();
   500	      const tokenRestored = restoreToken();
   501	      if (!profilesRestored || !activeRestored || !tokenRestored) return false;
   502	      return false;
   503	    }
   504	  }
   505	  const profiles = readServerProfiles();
   506	  notifyProfileChange({
   507	    type: "deleted",
   508	    deletedProfileId: id,
   509	    knownProfileIds: profiles.status === "available"
   510	      ? { status: "available", ids: profiles.profiles.map((candidate) => candidate.id) }
   511	      : { status: "unavailable" },
   512	  });
   513	  return true;
   514	}
   515	
   516	/** Migrate legacy single-server config to profile system */
   517	export function migrateToProfiles(): void {
   518	  const profiles = getProfiles();
   519	  if (profiles.length > 0) {
   520	    const activeId = getActiveProfileId();
   521	    const activeProfile = profiles.find((profile) => profile.id === activeId);
   522	    const targetProfile = activeProfile ?? profiles[0];
   523	    if (!activeProfile) setActiveProfile(targetProfile.id);
   524	
   525	    let legacyUrl: string | null = null;
   526	    try {
   527	      legacyUrl = localStorage.getItem(KEY_URL);
   528	    } catch {
   529	      // ignore
   530	    }
   531	    const existingToken = getAuthToken();
   532	    const legacyMatchesTarget =
   533	      legacyUrl !== null &&
   534	      !haveServerUrlsChanged(legacyUrl, targetProfile.url);
   535	    if (existingToken) {
   536	      if (!legacyMatchesTarget) {
   537	        // An unbound legacy token must not be copied to an unrelated profile.
   538	        clearAuthToken();
   539	        return;
   540	      }
   541	      if (!getAuthToken(targetProfile.id)) {
   542	        setAuthToken(existingToken, targetProfile.id);
   543	      }
   544	      if (getAuthToken(targetProfile.id)) clearAuthToken();
   545	    }
   546	    return;
   547	  }
   548	
   549	  let persistedUrl: string | null = null;
   550	  try {
   551	    persistedUrl = localStorage.getItem(KEY_URL);
   552	  } catch {
   553	    persistedUrl = null;
   554	  }
   555	  const existingUsername = getAuthUsername();
   556	  const existingToken = getAuthToken();
   557	  const existingUrl = persistedUrl ?? getConfiguredServerUrl();
   558	
   559	  if (existingUrl && isHttpServerUrl(normalizeServerUrl(existingUrl))) {
   560	    const profile = createProfile({
   561	      name: "Default Server",
   562	      url: normalizeServerUrl(existingUrl),
   563	      authType: "basic",
   564	      username: existingUsername || undefined,
   565	    });
   566	    setActiveProfile(profile.id);
   567	    if (existingToken && persistedUrl) {
   568	      setAuthToken(existingToken, profile.id);
   569	      if (getAuthToken(profile.id)) clearAuthToken();
   570	    } else if (existingToken) {
   571	      // Environment configuration does not bind an old legacy token safely.
   572	      clearAuthToken();
   573	    }
   574	  } else if (existingToken) {
   575	    // Without a URL there is no safe backend binding for a legacy token.
   576	    clearAuthToken();
   577	  }
   578	}
   579	
   580	function notifyProfileChange(event?: ServerProfileChange): void {
   581	  profileChangeVersion += 1;
   582	  if (event) for (const listener of profileChangeListeners) listener(event);
   583	  if (typeof window !== "undefined") window.dispatchEvent(new Event(PROFILE_CHANGED_EVENT));
   584	}
   585	
   586	/** Monotonic revision for active profile, profile metadata, and token changes. */
   587	export function getProfileChangeVersion(): number {
   588	  return profileChangeVersion;
   589	}
   590	
   591	/** Subscribe to active-profile and profile-list changes in this tab and other tabs. */
   592	export function subscribeToProfileChanges(callback: (event: ServerProfileChange) => void): () => void {
   593	  if (typeof window === "undefined") return () => {};
   594	
   595	  profileChangeListeners.add(callback);
   596	  const onProfileChange = () => callback({ type: "activeChanged", activeProfileId: getActiveProfileId() });
   597	  const onStorage = (event: StorageEvent) => {
   598	    if (
   599	      event.key === KEY_ACTIVE_PROFILE ||
   600	      event.key === KEY_PROFILES ||
   601	      event.key === KEY_TOKEN ||
   602	      event.key?.startsWith(`${KEY_TOKEN}_`)
   603	    ) {
   604	      profileChangeVersion += 1;
   605	      callback({ type: "activeChanged", activeProfileId: getActiveProfileId() });
   606	    }
   607	  };
   608	  window.addEventListener(PROFILE_CHANGED_EVENT, onProfileChange);
   609	  window.addEventListener("storage", onStorage);
   610	  return () => {
   611	    profileChangeListeners.delete(callback);
   612	    window.removeEventListener(PROFILE_CHANGED_EVENT, onProfileChange);
   613	    window.removeEventListener("storage", onStorage);
   614	  };
   615	}
